CREATE DATABASE BD_BancoFisclase ON  PRIMARY (     NAME = 'BD_BancoFisclase_Data',     FILENAME = 'C:\SQLData\BD_BancoFisclase_Data.mdf',     SIZE = 20MB,     MAXSIZE = 100MB,     FILEGROWTH = 5MB ) LOG ON (     NAME = 'BD_BancoFisclase_Log',     FILENAME = 'C:\SQLData\BD_BancoFisclase_Log.ldf',     SIZE = 10MB,     MAXSIZE = 50MB,     FILEGROWTH = 5MB ); GO  USE BD_BancoFisclase --- ===================================================== --- Estructura de la base de datos (CREATE TABLE) --- ===================================================== -- Crear tabla Cliente con dirección normalizada CREATE TABLE Cliente (     cliente_id INT IDENTITY(1,1) NOT NULL,     nombre NVARCHAR(100) NOT NULL,     email NVARCHAR(100) NOT NULL,     telefono NVARCHAR(20),     calle NVARCHAR(100),     numero NVARCHAR(20),     ciudad NVARCHAR(50),     estado_provincia NVARCHAR(50),     codigo_postal NVARCHAR(20),     pais NVARCHAR(50),     fecha_registro DATETIME DEFAULT GETDATE(),     activo BIT DEFAULT 1,     CONSTRAINT PK_Cliente PRIMARY KEY CLUSTERED (cliente_id),     CONSTRAINT UQ_Cliente_Email UNIQUE (email) );  -- Crear tabla TipoCuenta CREATE TABLE TipoCuenta (     tipo_cuenta_id INT IDENTITY(1,1) NOT NULL,     nombre NVARCHAR(50) NOT NULL,     descripcion NVARCHAR(200),     CONSTRAINT PK_TipoCuenta PRIMARY KEY CLUSTERED (tipo_cuenta_id),     CONSTRAINT UQ_TipoCuenta_Nombre UNIQUE (nombre) );  -- Crear tabla Cuenta CREATE TABLE Cuenta (     cuenta_id INT IDENTITY(1,1) NOT NULL,     cliente_id INT NOT NULL,     tipo_cuenta_id INT NOT NULL,     numero_cuenta NVARCHAR(20) NOT NULL,     saldo DECIMAL(18,2) NOT NULL DEFAULT 0,     fecha_apertura DATETIME DEFAULT GETDATE(),     activa BIT DEFAULT 1,     CONSTRAINT PK_Cuenta PRIMARY KEY CLUSTERED (cuenta_id),     CONSTRAINT FK_Cuenta_Cliente FOREIGN KEY (cliente_id)          REFERENCES Cliente(cliente_id)         ON DELETE CASCADE         ON UPDATE CASCADE,     CONSTRAINT FK_Cuenta_TipoCuenta FOREIGN KEY (tipo_cuenta_id)          REFERENCES TipoCuenta(tipo_cuenta_id)         ON DELETE NO ACTION         ON UPDATE CASCADE,     CONSTRAINT UQ_Cuenta_Numero UNIQUE (numero_cuenta),     CONSTRAINT CK_Cuenta_SaldoNoNegativo CHECK (saldo >= 0) );  -- Crear tabla Usuario CREATE TABLE Usuario (     usuario_id INT IDENTITY(1,1) NOT NULL,     cliente_id INT NOT NULL,     username NVARCHAR(50) NOT NULL,     password_hash NVARCHAR(64) NOT NULL,     salt NVARCHAR(32) NOT NULL,     intentos_fallidos INT DEFAULT 0,     bloqueado BIT DEFAULT 0,     fecha_creacion DATETIME DEFAULT GETDATE(),     fecha_ultimo_login DATETIME, 	es_admin BIT DEFAULT 0,     CONSTRAINT PK_Usuario PRIMARY KEY CLUSTERED (usuario_id),     CONSTRAINT FK_Usuario_Cliente FOREIGN KEY (cliente_id)          REFERENCES Cliente(cliente_id)         ON DELETE CASCADE         ON UPDATE CASCADE,     CONSTRAINT UQ_Usuario_Username UNIQUE (username),     CONSTRAINT CK_Usuario_IntentosFallidos CHECK (intentos_fallidos >= 0) ); ALTER TABLE Usuario  ADD es_admin BIT DEFAULT 0;  -- Crear tabla de referencia TipoTransaccion CREATE TABLE TipoTransaccion (     tipo_transaccion_id INT IDENTITY(1,1) NOT NULL,     nombre NVARCHAR(50) NOT NULL,     descripcion NVARCHAR(200),     CONSTRAINT PK_TipoTransaccion PRIMARY KEY CLUSTERED (tipo_transaccion_id),     CONSTRAINT UQ_TipoTransaccion_Nombre UNIQUE (nombre) );  -- Crear tabla de referencia EstadoTransaccion CREATE TABLE EstadoTransaccion (     estado_transaccion_id INT IDENTITY(1,1) NOT NULL,     nombre NVARCHAR(20) NOT NULL,     descripcion NVARCHAR(100),     CONSTRAINT PK_EstadoTransaccion PRIMARY KEY CLUSTERED (estado_transaccion_id),     CONSTRAINT UQ_EstadoTransaccion_Nombre UNIQUE (nombre) );  -- Crear tabla Transaccion con referencias adecuadas CREATE TABLE Transaccion (     transaccion_id INT IDENTITY(1,1) NOT NULL,     tipo_transaccion_id INT NOT NULL,     estado_transaccion_id INT NOT NULL,     monto DECIMAL(18,2) NOT NULL,     descripcion NVARCHAR(200),     fecha DATETIME DEFAULT GETDATE(),     fecha_actualizacion DATETIME,     usuario_id INT, -- Quién inició la transacción 	cuenta_destino_id INT NULL     CONSTRAINT FK_Transaccion_CuentaDestino FOREIGN KEY (cuenta_destino_id)  		REFERENCES Cuenta(cuenta_id), 	cuenta_origen_id INT NULL     CONSTRAINT FK_Transaccion_CuentaOrigen FOREIGN KEY (cuenta_origen_id)  		REFERENCES Cuenta(cuenta_id),     CONSTRAINT PK_Transaccion PRIMARY KEY CLUSTERED (transaccion_id),     CONSTRAINT FK_Transaccion_TipoTransaccion FOREIGN KEY (tipo_transaccion_id)          REFERENCES TipoTransaccion(tipo_transaccion_id),     CONSTRAINT FK_Transaccion_EstadoTransaccion FOREIGN KEY (estado_transaccion_id)          REFERENCES EstadoTransaccion(estado_transaccion_id),     CONSTRAINT FK_Transaccion_Usuario FOREIGN KEY (usuario_id)          REFERENCES Usuario(usuario_id),     CONSTRAINT CK_Transaccion_MontoPositivo CHECK (monto > 0) );  -- Crear tabla Movimiento CREATE TABLE Movimiento (     movimiento_id INT IDENTITY(1,1) NOT NULL,     cuenta_id INT NOT NULL,     transaccion_id INT NOT NULL,     monto_debito DECIMAL(18,2) DEFAULT 0,     monto_credito DECIMAL(18,2) DEFAULT 0,     saldo_resultante DECIMAL(18,2) NOT NULL,     fecha DATETIME DEFAULT GETDATE(),     CONSTRAINT PK_Movimiento PRIMARY KEY CLUSTERED (movimiento_id),     CONSTRAINT FK_Movimiento_Cuenta FOREIGN KEY (cuenta_id)          REFERENCES Cuenta(cuenta_id)         ON DELETE NO ACTION         ON UPDATE CASCADE,     CONSTRAINT FK_Movimiento_Transaccion FOREIGN KEY (transaccion_id)          REFERENCES Transaccion(transaccion_id)         ON DELETE CASCADE         ON UPDATE CASCADE,     CONSTRAINT CK_Movimiento_MontosNoNegativos CHECK (monto_debito >= 0 AND monto_credito >= 0),     CONSTRAINT CK_Movimiento_DebitoOCredito CHECK (         (monto_debito > 0 AND monto_credito = 0) OR          (monto_debito = 0 AND monto_credito > 0)     ) );  -- Crear tabla Notificacion para seguimiento de correos CREATE TABLE Notificacion (     notificacion_id INT IDENTITY(1,1) NOT NULL,     cliente_id INT NOT NULL,     tipo NVARCHAR(50) NOT NULL, -- 'ResumenDiario', 'AlertaSeguridad', etc.     asunto NVARCHAR(200) NOT NULL,     contenido NVARCHAR(MAX),     fecha_envio DATETIME DEFAULT GETDATE(),     estado NVARCHAR(20) DEFAULT 'Enviada', -- 'Enviada', 'Fallida', 'Pendiente'     CONSTRAINT PK_Notificacion PRIMARY KEY CLUSTERED (notificacion_id),     CONSTRAINT FK_Notificacion_Cliente FOREIGN KEY (cliente_id)          REFERENCES Cliente(cliente_id) );  --- ===================================================== --- Inserción de datos iniciales (INSERT) --- ===================================================== -- Insertar tipos de cuenta INSERT INTO TipoCuenta (nombre, descripcion) VALUES  (N'AHORRO', N'Cuenta de ahorros personal'), (N'CORRIENTE', N'Cuenta corriente personal'), (N'CREDITO', N'Tarjeta de crédito'), (N'DEBITO', N'Tarjeta de débito');  -- Insertar tipos de transacción INSERT INTO TipoTransaccion (nombre, descripcion) VALUES  (N'TRANSFER_INTERNO', N'Transferencia entre cuentas del mismo cliente'), (N'TRANSFER_EXTERNO', N'Transferencia a cuentas de otros clientes'), (N'DEPOSITO', N'Depósito de efectivo'), (N'RETIRO', N'Retiro de efectivo');  -- Insertar estados de transacción (NUEVOS VALORES) INSERT INTO EstadoTransaccion (nombre, descripcion) VALUES  ('COMPLETADO', 'Transacción completada exitosamente'), ('RECHAZADO', 'Transacción rechazada'), ('PENDIENTE', 'Transacción pendiente de procesamiento');   --- ===================================================== --- Procedimientos Almacenados (CREATE OR ALTER PROCEDURE) --- =====================================================  CREATE OR ALTER PROCEDURE sp_LoginValidate     @username NVARCHAR(50),     @password NVARCHAR(100),     @loginSuccess BIT OUTPUT,     @isLocked BIT OUTPUT,     @cliente_id INT OUTPUT,     @message NVARCHAR(100) OUTPUT,     @es_admin BIT OUTPUT AS BEGIN     DECLARE @storedHash NVARCHAR(64)     DECLARE @salt NVARCHAR(32)     DECLARE @attempts INT     DECLARE @blocked BIT          -- Se inicializan los parámetros para evitar errores     SET @loginSuccess = 0     SET @isLocked = 0     SET @cliente_id = 0     SET @message = ''          -- Validar si existe el usuario con contraseña hash y salt     SELECT          @storedHash = password_hash,          @salt = salt,          @attempts = intentos_fallidos,          @blocked = bloqueado,         @cliente_id = cliente_id,         @es_admin = es_admin     FROM Usuario      WHERE username = @username          -- Para validar si el usuario no existe     IF @storedHash IS NULL     BEGIN         SET @message = 'Usuario no encontrado'         RETURN     END          -- Validar si la cuenta está bloqueada.     IF @blocked = 1     BEGIN         SET @isLocked = 1         SET @message = 'Cuenta bloqueada. Contacte al administrador.'         RETURN     END          -- Calcula la contraseña hash con el salt     DECLARE @inputHash VARBINARY(64)     SET @inputHash = HASHBYTES('SHA2_256', @password + @salt)          -- Comparar hash     IF @inputHash = @storedHash     BEGIN         -- Login exitoso         SET @loginSuccess = 1         SET @message = 'Login exitoso'                  -- Reinicia los intentos fallidos a 0 y registra la fecha del último login         UPDATE Usuario          SET intentos_fallidos = 0,             fecha_ultimo_login = GETDATE()         WHERE username = @username     END     ELSE     BEGIN         -- Login fallido         SET @message = 'Credenciales incorrectas'                  -- Incrementar intentos fallidos         UPDATE Usuario          SET intentos_fallidos = intentos_fallidos + 1         WHERE username = @username                  -- Validar si la cuenta debería estar bloqueada         IF (SELECT intentos_fallidos FROM Usuario WHERE username = @username) >= 3         BEGIN             UPDATE Usuario              SET bloqueado = 1             WHERE username = @username                          SET @isLocked = 1             SET @message = 'Cuenta bloqueada por demasiados intentos fallidos'         END     END END; GO  CREATE OR ALTER PROCEDURE sp_TransferenciaInterna     @cuenta_origen_id INT,     @cuenta_destino_id INT,     @monto DECIMAL(18,2),     @descripcion NVARCHAR(200) = NULL,     @usuario_id INT, -- Sirve para ver quién inició la transacción     @transaccion_id INT OUTPUT,     @message NVARCHAR(200) OUTPUT AS BEGIN     SET NOCOUNT ON;          DECLARE @saldo_origen DECIMAL(18,2)     DECLARE @activa_origen BIT     DECLARE @activa_destino BIT     DECLARE @cliente_origen INT     DECLARE @cliente_destino INT          SET @transaccion_id = 0     SET @message = ''          -- Validar monto     IF @monto <= 0     BEGIN         SET @message = 'El monto debe ser mayor que cero'         RETURN     END          -- Obtener cuenta de origen     SELECT          @saldo_origen = saldo,         @activa_origen = activa,         @cliente_origen = cliente_id     FROM Cuenta      WHERE cuenta_id = @cuenta_origen_id          -- Validar si la cuenta de origen existe     IF @saldo_origen IS NULL     BEGIN         SET @message = 'Cuenta de origen no encontrada'         RETURN     END          -- Obtener cuenta de destino     SELECT          @activa_destino = activa,         @cliente_destino = cliente_id     FROM Cuenta      WHERE cuenta_id = @cuenta_destino_id          -- Validar si la cuenta de destino existe     IF @activa_destino IS NULL     BEGIN         SET @message = 'Cuenta de destino no encontrada'         RETURN     END          -- Validar si las cuentas son del mismo cliente     IF @cliente_origen != @cliente_destino     BEGIN         SET @message = 'Las cuentas deben pertenecer al mismo cliente'         RETURN     END          -- Validar si las cuentas están activas     IF @activa_origen = 0 OR @activa_destino = 0     BEGIN         SET @message = 'Una o ambas cuentas están inactivas'         RETURN     END          -- Validar si tiene suficiente fondo     IF @saldo_origen < @monto     BEGIN         SET @message = 'Fondos insuficientes en la cuenta de origen'         RETURN     END          BEGIN TRY         BEGIN TRANSACTION;         		-- Crear un log de la transacción         DECLARE @tipo_transferencia_id INT =              (SELECT tipo_transaccion_id FROM TipoTransaccion WHERE nombre = 'TRANSFER_INTERNO');         DECLARE @estado_completado_id INT =              (SELECT estado_transaccion_id FROM EstadoTransaccion WHERE nombre = 'COMPLETADO');           			INSERT INTO Transaccion ( 				tipo_transaccion_id,  				estado_transaccion_id, 				monto,  				descripcion, 				usuario_id, 				cuenta_origen_id, 				cuenta_destino_id 			) 			VALUES ( 				@tipo_transferencia_id, 				@estado_completado_id, 				@monto,  				@descripcion, 				@usuario_id, 				@cuenta_origen_id, 				@cuenta_destino_id 			)                  SET @transaccion_id = SCOPE_IDENTITY()                  -- Actualiza la cuenta de origen         UPDATE Cuenta          SET saldo = saldo - @monto         WHERE cuenta_id = @cuenta_origen_id                  -- Registrar el movimiento         INSERT INTO Movimiento (             cuenta_id,              transaccion_id,              monto_debito,              saldo_resultante         )         SELECT              @cuenta_origen_id,              @transaccion_id,              @monto,              saldo         FROM Cuenta          WHERE cuenta_id = @cuenta_origen_id                  -- Actualizar cuenta de destino         UPDATE Cuenta          SET saldo = saldo + @monto         WHERE cuenta_id = @cuenta_destino_id                  -- Registrar movimiento         INSERT INTO Movimiento (             cuenta_id,              transaccion_id,              monto_credito,              saldo_resultante         )         SELECT              @cuenta_destino_id,              @transaccion_id,              @monto,              saldo         FROM Cuenta          WHERE cuenta_id = @cuenta_destino_id                  COMMIT TRANSACTION;                  SET @message = 'Transferencia interna completada exitosamente'     END TRY     BEGIN CATCH         IF @@TRANCOUNT > 0             ROLLBACK TRANSACTION;                      SET @message = 'Error en la transferencia: ' + ERROR_MESSAGE()         SET @transaccion_id = 0     END CATCH END; GO  CREATE OR ALTER PROCEDURE sp_TransferenciaExterna     @cuenta_origen_id INT,     @numero_cuenta_destino_id NVARCHAR(20),     @monto DECIMAL(18,2),     @descripcion NVARCHAR(200) = NULL,     @usuario_id INT, -- Para ver quién inicia la transferencia     @transaccion_id INT OUTPUT,     @message NVARCHAR(200) OUTPUT AS BEGIN     SET NOCOUNT ON;          DECLARE @saldo_origen DECIMAL(18,2)     DECLARE @activa_origen BIT     DECLARE @cuenta_destino_id INT     DECLARE @activa_destino BIT 	     SET @transaccion_id = 0     SET @message = ''          -- Validar monto     IF @monto <= 0     BEGIN         SET @message = 'El monto debe ser mayor que cero'         RETURN     END          -- Obtener la cuenta de origen     SELECT          @saldo_origen = saldo,         @activa_origen = activa     FROM Cuenta      WHERE cuenta_id = @cuenta_origen_id          -- Validar si la cuenta existe     IF @saldo_origen IS NULL     BEGIN         SET @message = 'Cuenta de origen no encontrada'         RETURN     END          -- Obtener la cuenta de destino     SELECT          @cuenta_destino_id = cuenta_id,         @activa_destino = activa     FROM Cuenta      WHERE numero_cuenta = @numero_cuenta_destino_id          -- Validar si la cuenta existe     IF @cuenta_destino_id IS NULL     BEGIN         SET @message = 'Cuenta de destino no encontrada'         RETURN     END          -- Validar si las cuentas están activas     IF @activa_origen = 0 OR @activa_destino = 0     BEGIN         SET @message = N'Una o ambas cuentas están inactivas'         RETURN     END          -- Validar fondos suficientes     IF @saldo_origen < @monto     BEGIN         SET @message = 'Fondos insuficientes en la cuenta de origen'         RETURN     END          BEGIN TRY         BEGIN TRANSACTION;                  -- Crear un log de la transacción         DECLARE @estado_completado_id INT =              (SELECT estado_transaccion_id FROM EstadoTransaccion WHERE nombre = 'COMPLETADO'); 		DECLARE @tipo_transferencia_id INT =  			(SELECT tipo_transaccion_id FROM TipoTransaccion WHERE nombre = 'TRANSFER_EXTERNO');               			INSERT INTO Transaccion ( 			tipo_transaccion_id,  			estado_transaccion_id, 			monto,  			descripcion, 			usuario_id, 			cuenta_origen_id, 			cuenta_destino_id 			) 			VALUES ( 			@tipo_transferencia_id, 			@estado_completado_id, 			@monto,  			@descripcion, 			@usuario_id, 			@cuenta_origen_id, 			@cuenta_destino_id 			)                  SET @transaccion_id = SCOPE_IDENTITY()                  -- Actualizar la cuenta de origen         UPDATE Cuenta          SET saldo = saldo - @monto         WHERE cuenta_id = @cuenta_origen_id                  -- Registrar el movimiento         INSERT INTO Movimiento (             cuenta_id,              transaccion_id,              monto_debito,              saldo_resultante         )         SELECT              @cuenta_origen_id,              @transaccion_id,              @monto,              saldo         FROM Cuenta          WHERE cuenta_id = @cuenta_origen_id                  -- Actualizar la cuenta de destino         UPDATE Cuenta          SET saldo = saldo + @monto         WHERE cuenta_id = @cuenta_destino_id                  -- Registrar el movimiento         INSERT INTO Movimiento (             cuenta_id,              transaccion_id,              monto_credito,              saldo_resultante         )         SELECT              @cuenta_destino_id,              @transaccion_id,              @monto,              saldo         FROM Cuenta          WHERE cuenta_id = @cuenta_destino_id                  COMMIT TRANSACTION;                  SET @message = 'Transferencia externa completada exitosamente'     END TRY     BEGIN CATCH         IF @@TRANCOUNT > 0             ROLLBACK TRANSACTION;                      SET @message = 'Error en la transferencia: ' + ERROR_MESSAGE()         SET @transaccion_id = 0     END CATCH END; GO  CREATE OR ALTER PROCEDURE sp_ObtenerHistorialTransacciones     @cliente_id INT,     @dias INT = 30 AS BEGIN     SET NOCOUNT ON;          SELECT          t.transaccion_id,         tt.nombre AS tipo_transaccion,         t.monto,         et.nombre AS estado,         t.descripcion,         t.fecha,         t.usuario_id,         co.numero_cuenta AS cuenta_origen_id_numero,         cd.numero_cuenta AS cuenta_destino_id_numero,         tco.nombre AS tipo_cuenta_origen_id,         tcd.nombre AS tipo_cuenta_destino_id     FROM Transaccion t     INNER JOIN TipoTransaccion tt ON t.tipo_transaccion_id = tt.tipo_transaccion_id     INNER JOIN EstadoTransaccion et ON t.estado_transaccion_id = et.estado_transaccion_id     LEFT JOIN Cuenta co ON t.cuenta_origen_id = co.cuenta_id     LEFT JOIN Cuenta cd ON t.cuenta_destino_id = cd.cuenta_id     LEFT JOIN TipoCuenta tco ON co.tipo_cuenta_id = tco.tipo_cuenta_id     LEFT JOIN TipoCuenta tcd ON cd.tipo_cuenta_id = tcd.tipo_cuenta_id     WHERE (t.cuenta_origen_id IN (SELECT cuenta_id FROM Cuenta WHERE cliente_id = @cliente_id)           OR t.cuenta_destino_id IN (SELECT cuenta_id FROM Cuenta WHERE cliente_id = @cliente_id))     AND t.fecha >= DATEADD(DAY, -@dias, GETDATE())     ORDER BY t.fecha DESC; END; GO  -- Procedimiento para obtener notificaciones de un cliente CREATE OR ALTER PROCEDURE sp_ObtenerNotificacionesCliente     @cliente_id INT,     @dias INT = 30 -- Opcional: para filtrar por días AS BEGIN     SET NOCOUNT ON;      SELECT         notificacion_id,         tipo,         asunto,         contenido,         fecha_envio,         estado     FROM Notificacion     WHERE cliente_id = @cliente_id     AND fecha_envio >= DATEADD(DAY, -@dias, GETDATE())     ORDER BY fecha_envio DESC; END; GO  CREATE OR ALTER PROCEDURE sp_EnviarResumenCorreo     @cliente_id INT AS BEGIN     SET NOCOUNT ON;          -- Email fijo para pruebas     DECLARE @email_pruebas NVARCHAR(100) = 'andre.s.reboulet@gmail.com'          DECLARE @nombre NVARCHAR(100)     DECLARE @movimientos_count INT     DECLARE @subject NVARCHAR(100)     DECLARE @body NVARCHAR(MAX)     DECLARE @saldo_total DECIMAL(18,2)     DECLARE @saldo_anterior DECIMAL(18,2)     DECLARE @detalle_movimientos NVARCHAR(MAX) = ''          -- Obtener información del cliente y saldo actual     SELECT         @nombre = c.nombre,         @saldo_total = ISNULL(SUM(cu.saldo), 0)     FROM Cliente c     LEFT JOIN Cuenta cu ON c.cliente_id = cu.cliente_id AND cu.activa = 1     WHERE c.cliente_id = @cliente_id     GROUP BY c.nombre          -- Obtener saldo de cierre del día anterior (corregido)     SELECT @saldo_anterior = ISNULL(SUM(m.saldo_resultante), 0)     FROM Movimiento m     JOIN Cuenta cu ON m.cuenta_id = cu.cuenta_id     WHERE cu.cliente_id = @cliente_id     AND m.fecha = (         SELECT MAX(fecha)          FROM Movimiento m2          JOIN Cuenta cu2 ON m2.cuenta_id = cu2.cuenta_id         WHERE cu2.cliente_id = @cliente_id         AND CAST(m2.fecha AS DATE) = CAST(DATEADD(DAY, -1, GETDATE()) AS DATE)     )          -- Verificar si el cliente tiene movimientos hoy     SELECT @movimientos_count = COUNT(*)     FROM vw_MovimientosDelDia     WHERE cliente_id = @cliente_id          -- Obtener detalle de movimientos si los hay (corregido)     IF @movimientos_count > 0     BEGIN         SELECT @detalle_movimientos = @detalle_movimientos +              CONCAT(                 'Fecha: ', FORMAT(t.fecha, 'dd/MM/yyyy HH:mm:ss'), ' | ',                 'Tipo: ', tt.nombre, ' | ',                 'Monto: ', FORMAT(t.monto, 'C'), ' | ',                 'Cuenta Origen: ', ISNULL(c_origen.numero_cuenta, 'N/A'), ' | ',                 'Cuenta Destino: ', ISNULL(c_destino.numero_cuenta, 'N/A'), ' | ',                 'Descripción: ', ISNULL(t.descripcion, ''),                  CHAR(13), CHAR(10))         FROM Transaccion t         JOIN TipoTransaccion tt ON t.tipo_transaccion_id = tt.tipo_transaccion_id         JOIN EstadoTransaccion et ON t.estado_transaccion_id = et.estado_transaccion_id         LEFT JOIN Movimiento m ON t.transaccion_id = m.transaccion_id         LEFT JOIN Cuenta c_origen ON m.cuenta_id = c_origen.cuenta_id AND m.monto_debito > 0         LEFT JOIN Cuenta c_destino ON m.cuenta_id = c_destino.cuenta_id AND m.monto_credito > 0         WHERE (c_origen.cliente_id = @cliente_id OR c_destino.cliente_id = @cliente_id)         AND CAST(t.fecha AS DATE) = CAST(GETDATE() AS DATE)         AND et.nombre = 'COMPLETADO'         ORDER BY t.fecha DESC     END          -- Configurar contenido del correo según si hay movimientos o no     IF @movimientos_count = 0     BEGIN         SET @subject = CONCAT('Sin movimientos - ', FORMAT(GETDATE(), 'dd/MM/yyyy'), ' - Banco Dinamo (Para: ', @nombre, ')')         SET @body = CONCAT(             '<html><body>',             '<h2>Estimado ', @nombre, ',</h2>',             N'<p>Hoy no registraste ningún movimiento en tus cuentas.</p>',             '<ul>',             '<li><strong>Saldo anterior:</strong> ', FORMAT(@saldo_anterior, 'C'), '</li>',             '<li><strong>Saldo actual:</strong> ', FORMAT(@saldo_total, 'C'), '</li>',             '</ul>',             '<p>Gracias por confiar en Banco Dinamo.</p>',             '<p>Atentamente,<br>El equipo de Banco Dinamo</p>',             '</body></html>'         )     END     ELSE     BEGIN         SET @subject = CONCAT('Resumen diario - ', FORMAT(GETDATE(), 'dd/MM/yyyy'), ' - Banco Dinamo (Para: ', @nombre, ')')         SET @body = CONCAT(             '<html><body>',             '<h2>Estimado ', @nombre, ',</h2>',             '<p>Resumen de tus movimientos del día ', FORMAT(GETDATE(), 'dd/MM/yyyy'), ':</p>',             '<ul>',             '<li><strong>Saldo anterior:</strong> ', FORMAT(@saldo_anterior, 'C'), '</li>',             '<li><strong>Movimientos hoy:</strong> ', @movimientos_count, '</li>',             '<li><strong>Saldo actual:</strong> ', FORMAT(@saldo_total, 'C'), '</li>',             '</ul>',             '<h3>Detalle de movimientos:</h3>',             '<pre>', @detalle_movimientos, '</pre>',             '<p>Gracias por confiar en Banco Dinamo.</p>',             '<p>Atentamente,<br>El equipo de Banco Dinamo</p>',             '<small>Este es un mensaje automático, por favor no responda a este correo.</small>',             '</body></html>'         )     END          -- Enviar correo (siempre al email fijo de pruebas)     EXEC msdb.dbo.sp_send_dbmail         @profile_name = 'BancoDinamoProfile',         @recipients = @email_pruebas,         @subject = @subject,         @body = @body,         @body_format = 'HTML';          -- Registrar notificación     INSERT INTO Notificacion (         cliente_id,         tipo,         asunto,         contenido,         estado     )     VALUES (         @cliente_id,         'ResumenDiario',         @subject,         @body,         'Enviada'     ); END; GO   CREATE OR ALTER PROCEDURE sp_EnviarResumenesDiarios AS BEGIN     SET NOCOUNT ON;          DECLARE @cliente_id INT;     DECLARE @email_cliente_actual NVARCHAR(100);     DECLARE @exito BIT;     DECLARE @mensaje_error NVARCHAR(500);     DECLARE @mail_enabled BIT;      -- Verificar si Database Mail está habilitado     SELECT @mail_enabled = CONVERT(BIT, ISNULL(value, value_in_use))     FROM sys.configurations     WHERE name = 'Database Mail XPs';      IF @mail_enabled = 0     BEGIN         RAISERROR('Database Mail no está habilitado en esta instancia de SQL Server', 16, 1);         RETURN;     END      -- Crear tabla temporal para rastrear resultados     CREATE TABLE #ResultadosEnvio (         cliente_id INT,         email NVARCHAR(100),         exito BIT,         mensaje_error NVARCHAR(500),         fecha_envio DATETIME DEFAULT GETDATE()     );      -- Cursor para iterar sobre todos los clientes activos     DECLARE client_cursor CURSOR LOCAL FAST_FORWARD FOR     SELECT cliente_id, email     FROM Cliente     WHERE activo = 1;      OPEN client_cursor;     FETCH NEXT FROM client_cursor INTO @cliente_id, @email_cliente_actual;      WHILE @@FETCH_STATUS = 0     BEGIN         BEGIN TRY             -- Enviar resumen para cada cliente             EXEC sp_EnviarResumenCorreo @cliente_id;              -- Registrar éxito             INSERT INTO #ResultadosEnvio (cliente_id, email, exito)             VALUES (@cliente_id, @email_cliente_actual, 1);         END TRY         BEGIN CATCH             -- Registrar fallo             SET @mensaje_error = ERROR_MESSAGE();              INSERT INTO #ResultadosEnvio (cliente_id, email, exito, mensaje_error)             VALUES (@cliente_id, @email_cliente_actual, 0, @mensaje_error);              -- Registrar notificación de error             INSERT INTO Notificacion (                 cliente_id,                 tipo,                 asunto,                 contenido,                 estado             )             VALUES (                 @cliente_id,                 'ErrorEnvio',                 'Error al enviar resumen diario',                 @mensaje_error,                 'Fallida'             );         END CATCH;          FETCH NEXT FROM client_cursor INTO @cliente_id, @email_cliente_actual;     END;      CLOSE client_cursor;     DEALLOCATE client_cursor;      -- Solo intentar enviar resumen al admin si Database Mail está habilitado     IF @mail_enabled = 1     BEGIN         BEGIN TRY             -- Enviar resumen de envíos al administrador             DECLARE @total_clientes INT, @exitosos INT, @fallidos INT;             DECLARE @admin_subject NVARCHAR(200);             DECLARE @admin_body NVARCHAR(MAX);             DECLARE @email NVARCHAR(100) = 'andre.s.reboulet@gmail.com';              SELECT                 @total_clientes = COUNT(*),                 @exitosos = SUM(CASE WHEN exito = 1 THEN 1 ELSE 0 END),                 @fallidos = SUM(CASE WHEN exito = 0 THEN 1 ELSE 0 END)             FROM #ResultadosEnvio;              SET @admin_subject = CONCAT(N'Resumen de envíos diarios - ', FORMAT(GETDATE(), 'dd/MM/yyyy'));             SET @admin_body = CONCAT(                 N'<html><body>',                 N'<h2>Resumen de envíos diarios - ', FORMAT(GETDATE(), 'dd/MM/yyyy'), '</h2>',                 N'<p>Total clientes procesados: ', @total_clientes, '</p>',                 N'<p>Envíos exitosos: ', @exitosos, '</p>',                 N'<p>Envíos fallidos: ', @fallidos, '</p>',                 N'<p>Detalle de errores disponible en la tabla de notificaciones.</p>',                 N'</body></html>'             );              EXEC msdb.dbo.sp_send_dbmail                 @profile_name = N'BancoDinamoProfile',                 @recipients = @email,                 @subject = @admin_subject,                 @body = @admin_body,                 @body_format = 'HTML';         END TRY         BEGIN CATCH             -- Registrar error al enviar resumen admin             INSERT INTO Notificacion (                 cliente_id,                 tipo,                 asunto,                 contenido,                 estado             )             VALUES (                 4,                 N'AdminAlertError',                 N'Error al enviar resumen de envíos diarios',                 ERROR_MESSAGE(),                 'Fallida'             );         END CATCH;     END      -- Actualizar o insertar la alerta de administrador en la tabla Notificacion     IF EXISTS (SELECT 1 FROM Notificacion WHERE tipo = 'AdminAlert' AND CAST(fecha_envio AS DATE) = CAST(GETDATE() AS DATE))     BEGIN         UPDATE Notificacion         SET contenido = @admin_body,             asunto = @admin_subject,             estado = CASE WHEN @mail_enabled = 1 THEN 'Enviada' ELSE 'Fallida' END         WHERE tipo = 'AdminAlert'         AND CAST(fecha_envio AS DATE) = CAST(GETDATE() AS DATE);     END     ELSE     BEGIN         INSERT INTO Notificacion (             cliente_id,             tipo,             asunto,             contenido,             estado         )         VALUES (             4,             N'AdminAlert',             @admin_subject,             @admin_body,             CASE WHEN @mail_enabled = 1 THEN 'Enviada' ELSE 'Fallida' END         );     END;      -- Limpiar tabla temporal     DROP TABLE #ResultadosEnvio; END; GO --- ===================================================== --- Vistas (CREATE OR ALTER VIEW) --- =====================================================  CREATE OR ALTER VIEW vw_MovimientosDelDia AS SELECT      cl.cliente_id,     cl.nombre AS cliente_nombre,     cl.email AS cliente_email,     t.transaccion_id,     t.fecha,     tt.nombre AS tipo_transaccion,     t.monto,     t.descripcion,     c_origen.numero_cuenta AS cuenta_origen_id,     c_destino.numero_cuenta AS cuenta_destino_id,     m_debito.monto_debito,     m_credito.monto_credito,     et.nombre AS estado_transaccion,     u.username AS usuario_transaccion FROM Transaccion t  JOIN TipoTransaccion tt ON t.tipo_transaccion_id = tt.tipo_transaccion_id  JOIN EstadoTransaccion et ON t.estado_transaccion_id = et.estado_transaccion_id  JOIN Usuario u ON t.usuario_id = u.usuario_id  JOIN Movimiento m_debito ON t.transaccion_id = m_debito.transaccion_id AND m_debito.monto_debito > 0  JOIN Movimiento m_credito ON t.transaccion_id = m_credito.transaccion_id AND m_credito.monto_credito > 0  JOIN Cuenta c_origen ON m_debito.cuenta_id = c_origen.cuenta_id  JOIN Cuenta c_destino ON m_credito.cuenta_id = c_destino.cuenta_id  JOIN Cliente cl ON c_origen.cliente_id = cl.cliente_id OR c_destino.cliente_id = cl.cliente_id WHERE CAST(t.fecha AS DATE) = CAST(GETDATE() AS DATE) AND et.nombre = 'COMPLETADO';  GO;  CREATE OR ALTER VIEW vw_ResumenCliente AS SELECT      c.cliente_id,     c.nombre,     c.email,     c.telefono,     -- Cuentas activas e inactivas     COUNT(DISTINCT cu.cuenta_id) AS total_cuentas,     SUM(CASE WHEN cu.activa = 1 THEN 1 ELSE 0 END) AS cuentas_activas,     SUM(CASE WHEN cu.activa = 0 THEN 1 ELSE 0 END) AS cuentas_inactivas,     -- Saldo total solo de cuentas activas     SUM(CASE WHEN cu.activa = 1 THEN cu.saldo ELSE 0 END) AS saldo_total,     -- Última transacción real del cliente     (SELECT MAX(t.fecha)       FROM Transaccion t      JOIN Movimiento m ON t.transaccion_id = m.transaccion_id      JOIN Cuenta cu2 ON m.cuenta_id = cu2.cuenta_id      WHERE cu2.cliente_id = c.cliente_id) AS ultima_transaccion,     -- Usuarios asociados     (SELECT COUNT(*) FROM Usuario u WHERE u.cliente_id = c.cliente_id) AS usuarios_asociados FROM Cliente c  LEFT JOIN Cuenta cu ON c.cliente_id = cu.cliente_id GROUP BY c.cliente_id, c.nombre, c.email, c.telefono; GO  CREATE OR ALTER VIEW vw_AnalisisTransacciones AS SELECT      c.cliente_id,     c.nombre AS cliente_nombre,     tt.nombre AS tipo_transaccion,     COUNT(t.transaccion_id) AS cantidad_transacciones,     SUM(t.monto) AS monto_total,     AVG(t.monto) AS monto_promedio,     MIN(t.fecha) AS primera_transaccion,     MAX(t.fecha) AS ultima_transaccion,     et.nombre AS estado_mas_comun FROM Cliente c JOIN Cuenta cu ON c.cliente_id = cu.cliente_id JOIN Movimiento m ON cu.cuenta_id = m.cuenta_id JOIN Transaccion t ON m.transaccion_id = t.transaccion_id JOIN TipoTransaccion tt ON t.tipo_transaccion_id = tt.tipo_transaccion_id JOIN EstadoTransaccion et ON t.estado_transaccion_id = et.estado_transaccion_id GROUP BY c.cliente_id, c.nombre, tt.nombre, et.nombre; GO --- ==================================================== --- Consultas adicionales --- ====================================================  SELECT * FROM [dbo].[vw_MovimientosDelDia] SELECT * FROM [dbo].[vw_AnalisisTransacciones] SELECT * FROM [dbo].[vw_ResumenCliente]  --- ===================================================== --- Índices (CREATE INDEX) --- =====================================================  CREATE INDEX IX_Usuario_Username ON Usuario(username); CREATE INDEX IX_Cuenta_Cliente ON Cuenta(cliente_id); CREATE INDEX IX_Transaccion_Fecha ON Transaccion(fecha); CREATE INDEX IX_Movimiento_CuentaFecha ON Movimiento(cuenta_id, fecha);  --- ===================================================== --- Configuración de DBMail y Job de SQL Server --- =====================================================  -- Configuración de la cuenta de correo para DBMail EXECUTE msdb.dbo.sysmail_add_account_sp     @account_name = 'BancoDinamoMail',     @description = 'Cuenta de correo para notificaciones de Banco Dinamo',     @email_address = 'andre.s.reboulet@gmail.com',     @display_name = 'Notificaciones Banco Dinamo',     @mailserver_name = 'smtp.gmail.com',     @port = 587,     @username = 'andre.s.reboulet@gmail.com',     @password = 'wzcdyrcfuohauckp',     @enable_ssl = 1;  -- Configuración del perfil de correo para DBMail EXECUTE msdb.dbo.sysmail_add_profile_sp     @profile_name = 'BancoDinamoProfile',     @description = 'Perfil para notificaciones de Banco Dinamo';  -- Asociar la cuenta al perfil EXECUTE msdb.dbo.sysmail_add_profileaccount_sp     @profile_name = 'BancoDinamoProfile',     @account_name = 'BancoDinamoMail',     @sequence_number = 1;  USE msdb; GO  -- Crear el Job de SQL Server Agent EXEC msdb.dbo.sp_add_job     @job_name = 'ResumenDiarioMovimientos'; GO  -- Añadir el paso al Job para ejecutar el procedimiento de envío de resúmenes EXEC msdb.dbo.sp_add_jobstep     @job_name = 'ResumenDiarioMovimientos',     @step_name = 'EnviarResumenesClientes',     @subsystem = 'TSQL',     @command = 'EXEC BD_BancoFisclase.dbo.sp_EnviarResumenesDiarios',     @database_name = 'BD_BancoFisclase'; GO  -- Añadir la programación al Job (Diario a las 23:30) EXEC msdb.dbo.sp_add_schedule     @schedule_name = 'Diario_2330',     @freq_type = 4, -- Diario     @freq_interval = 1,     @active_start_time = 233000; -- 11:30 PM GO  -- Adjuntar la programación al Job EXEC msdb.dbo.sp_attach_schedule     @job_name = 'ResumenDiarioMovimientos',     @schedule_name = 'Diario_2330'; GO  -- Añadir el servidor al Job EXEC msdb.dbo.sp_add_jobserver     @job_name = 'ResumenDiarioMovimientos'; GO  -- Ejecutar el procedimiento de envío de resúmenes manualmente (para pruebas) EXEC sp_EnviarResumenesDiarios;  EXEC msdb.dbo.sp_start_job     @job_name = N'ResumenDiarioMovimientos'  